using System.ComponentModel;
using System.Text;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration -----------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Tools -------------------------------------------------------------------

var notebook = new ResearchNotebook();

IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var agent = new ChatClientAgent(chatClient, new ChatClientAgentOptions
{
    Name = "ResearchAgent",
    Description = "An AI research assistant that searches the web and takes notes to produce a research summary.",
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 4096,
        Tools =
        [
            AIFunctionFactory.Create(
                (string query) => WebSearchTool.SearchAsync(query),
                nameof(WebSearchTool.SearchAsync),
                "Searches the web for a query and returns a list of result snippets. Use this to gather information on a topic."),

            AIFunctionFactory.Create(
                ([Description("A concise heading for this note")] string title,
                 [Description("The note content — a fact, quote, or insight worth remembering")] string content) =>
                {
                    notebook.AddNote(title, content);
                    return $"Note saved: {title}";
                },
                "SaveNote",
                "Saves a research note. Use this to record important findings while researching."),

            AIFunctionFactory.Create(
                () => notebook.GetAllNotes(),
                "GetNotes",
                "Returns all previously saved research notes."),
        ],
    },
});

// --- Run the agent -----------------------------------------------------------

Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        AI Research Agent (MAF)           ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine();
Console.WriteLine($"Researching: {topic}");
Console.WriteLine("─────────────────────────────────────────────");

var systemPrompt = $"""
    You are a thorough research assistant. Your goal is to research the following topic
    and produce a well-organized summary.

    **Research process:**
    1. Search the web multiple times with varied queries to gather diverse perspectives.
    2. Save important findings as notes using the SaveNote tool.
    3. After gathering enough information (at least 3-5 searches), retrieve your notes.
    4. Produce a final, well-structured research summary with key findings, using markdown formatting.

    Topic to research: {topic}
    """;

var messages = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Please research the following topic thoroughly: {topic}"),
};

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
});

var response = await agent.RunAsync(messages, options: runOptions);

Console.WriteLine();
Console.WriteLine("═══════════════════════════════════════════════");
Console.WriteLine("                RESEARCH SUMMARY               ");
Console.WriteLine("═══════════════════════════════════════════════");
Console.WriteLine();

foreach (var message in response.Messages.Where(m => m.Role == ChatRole.Assistant))
{
    var text = message.Text;
    if (!string.IsNullOrWhiteSpace(text))
    {
        Console.WriteLine(text);
    }
}

if (notebook.Count > 0)
{
    Console.WriteLine();
    Console.WriteLine("───────────────────────────────────────────────");
    Console.WriteLine($"Research notes collected: {notebook.Count}");
}

// --- Tool implementations ----------------------------------------------------

/// <summary>Simulates a web search tool that returns results for a query.</summary>
static class WebSearchTool
{
    private static readonly HttpClient s_http = new()
    {
        Timeout = TimeSpan.FromSeconds(30),
    };

    public static async Task<string> SearchAsync(
        [Description("The search query to look up on the web")] string query)
    {
        // Uses a public search-snippet API when available; falls back to a
        // descriptive placeholder so the agent can still demonstrate its
        // research workflow without a live search key.
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await s_http.GetStringAsync(url);

            // Extract the abstract if DuckDuckGo returns one
            var doc = System.Text.Json.JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new StringBuilder();

            if (root.TryGetProperty("AbstractText", out var abs) && abs.GetString() is { Length: > 0 } abstractText)
            {
                results.AppendLine($"**Summary:** {abstractText}");
                if (root.TryGetProperty("AbstractSource", out var src))
                    results.AppendLine($"Source: {src.GetString()}");
                results.AppendLine();
            }

            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                var count = 0;
                foreach (var item in topics.EnumerateArray())
                {
                    if (count >= 5) break;
                    if (item.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } t)
                    {
                        results.AppendLine($"- {t}");
                        count++;
                    }
                }
            }

            var output = results.ToString();
            return string.IsNullOrWhiteSpace(output)
                ? $"No detailed results found for '{query}'. Try a different search query."
                : output;
        }
        catch (Exception ex)
        {
            return $"Search failed ({ex.GetType().Name}): {ex.Message}. Try rephrasing the query.";
        }
    }
}

/// <summary>A simple in-memory notebook for storing research notes.</summary>
sealed class ResearchNotebook
{
    private readonly List<(string Title, string Content)> _notes = [];

    public int Count => _notes.Count;

    public void AddNote(string title, string content)
    {
        _notes.Add((title, content));
    }

    public string GetAllNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
        {
            sb.AppendLine($"## Note {i + 1}: {_notes[i].Title}");
            sb.AppendLine(_notes[i].Content);
            sb.AppendLine();
        }

        return sb.ToString();
    }
}

